// rates 以某基准货币为 1 的相对汇率；convert 用 amount / fromRate * toRate
function convert(amount, from, to, rates){
  if(!(from in rates) || !(to in rates) || rates[from]===0) return null;
  return amount / rates[from] * rates[to];
}
function crossRate(from, to, rates){ return convert(1, from, to, rates); }
var DEFAULT_RATES={USD:1, CNY:7.2, EUR:0.92, JPY:150, GBP:0.79, HKD:7.8};
var EXPORTS={convert:convert, crossRate:crossRate, DEFAULT_RATES:DEFAULT_RATES};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CurrencyForgePure = EXPORTS; }
